function CaseTable({cases,onSelect}){return <div className="table-scroll"><table><thead><tr><th>{t("Публикация")}</th><th>{t("Платформа")}</th><th>{t("Категория")}</th><th>{t("Уровень риска")}</th><th>{t("Статус")}</th><th aria-label={t("Открыть кейс")}/></tr></thead><tbody>{cases.map(c=><tr key={c.id} onClick={()=>onSelect(c)}><td><button className="case-title" onClick={e=>{e.stopPropagation();onSelect(c);}}>{c.text||c.url||t('Без текста')}</button><div className="case-meta"><span>{c.author||`#${String(c.id).slice(-7)}`}</span><span>·</span><span>{date(c.createdAt)}</span>{c.demo&&<span className="demo-badge">DEMO</span>}</div></td><td><span className="platform"><PlatformIcon platform={c.platform}/>{t(PLATFORM_LABELS[c.platform]||c.platform||'Другое')}</span></td><td><span className="category-text">{t(CATEGORIES[c.analysis?.category]||'Не определено')}</span></td><td><div className="risk-cell"><Risk level={c.analysis?.level}/><span>{score(c)}<small>/100</small></span></div></td><td><span className={`status-pill ${c.status}`}><i/>{t(STATUS[c.status]||'Новый')}</span></td><td><ChevronRight className="muted" size={17}/></td></tr>)}</tbody></table></div>;}
function ActivityChart({cases}){const [days,setDays]=useState(7);const bars=Array.from({length:days},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(days-1-i));const records=cases.filter(c=>new Date(c.createdAt).toDateString()===d.toDateString());return {label:date(d),total:records.length,high:records.filter(c=>c.analysis?.level==='high').length};});const max=Math.max(4,...bars.map(b=>b.total));return <section className="panel activity-panel"><div className="panel-heading"><div><h2>{t("Активность проверок")}</h2><p>{t("Количество публикаций по дням")}</p></div><select className="period-select" aria-label={t("Период графика")} value={days} onChange={e=>setDays(Number(e.target.value))}><option value={7}>{t("7 дней")}</option><option value={14}>{t("14 дней")}</option><option value={30}>{t("30 дней")}</option></select></div><div className="activity-chart"><div className="chart-y">{[max,Math.round(max*.75),Math.round(max*.5),Math.round(max*.25),0].map((n,i)=><span key={i}>{n}</span>)}</div><div className="chart-plot"><div className="gridlines">{[0,1,2,3,4].map(i=><i key={i}/>)}</div><div className="bars">{bars.map((b,i)=><div key={i} className="bar-column"><div className="bar-slot" title={`${b.label}: ${b.total} · ${t('Высокий риск')}: ${b.high}`}><div className="bar" style={{height:`${b.total/max*100}%`}}><div className="bar-high" style={{height:`${b.total?b.high/b.total*100:0}%`}}/></div></div><span>{days<=14||i%5===0?b.label:''}</span></div>)}</div></div></div><div className="chart-legend"><span><i style={{background:'#d9e9e2'}}/>{t("Все проверки")}</span><span><i style={{background:'#488675'}}/>{t("Высокий риск")}</span>{!cases.length&&<span className="chart-no-data">{t("Нет проверок за период")}</span>}</div></section>;}
function CategoryChart({cases}){const all=Object.keys(CATEGORIES).map(id=>({id,count:cases.filter(c=>c.analysis?.category===id).length}));let cumulative=0;const stops=all.map(c=>{const start=cumulative;cumulative+=cases.length?c.count/cases.length*100:0;return `${COLORS[c.id]} ${start}% ${cumulative}%`;}).join(',');return <section className="panel category-panel"><div className="panel-heading"><div><h2>{t("Типы угроз")}</h2><p>{t("Распределение по ведущему сигналу")}</p></div><span className="round-icon"><Fingerprint size={18}/></span></div><div className="category-content"><div className="donut" role="img" aria-label={`${t('Типы угроз')}: ${cases.length}`} style={{background:cases.length?`conic-gradient(${stops})`:'#e8edeb'}}><div><strong>{cases.length}</strong><span>{t("всего кейсов")}</span></div></div><div className="category-legend">{all.map(c=><div key={c.id}><i style={{background:COLORS[c.id]}}/><span>{t(CATEGORIES[c.id])}</span><strong>{c.count}</strong></div>)}</div></div><div className="chart-footnote"><Info size={13}/>{t("Один кейс может содержать несколько признаков.")}</div></section>;}

function Analyze({prefill,onCreated,onImported,readOnly,mode,liveOnly}){const [text,setText]=useState(prefill?.text||''),[url,setUrl]=useState(prefill?.url||''),[platform,setPlatform]=useState(PLATFORMS.includes(prefill?.platform)?prefill.platform:'instagram'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[ocr,setOcr]=useState(''),[ocrBusy,setOcrBusy]=useState(false),[tab,setTab]=useState('text'),[importBusy,setImportBusy]=useState(false);const fileRef=useRef(),imageRef=useRef();useEffect(()=>{if(prefill){setText(prefill.text||'');setUrl(prefill.url||'');if(prefill.platform)setPlatform(normalizePlatform(prefill.platform));}},[prefill]);
 async function analyze(e){e.preventDefault();if(!mode||(!text.trim()&&!url.trim()))return;setBusy(true);setError('');try{const d=await api('/api/analyze',{method:'POST',body:JSON.stringify({text,url,platform})});onCreated(d.case||d,d.stored);}catch(e){setError(e.message);}finally{setBusy(false);}}
 async function recognize(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>12*1024*1024){setError(t('Выберите изображение размером до 12 МБ.'));return;}setOcrBusy(true);setOcr(t('Подготавливаем распознавание…'));setError('');try{const {createWorker}=await import('tesseract.js');const worker=await createWorker(['rus','kaz','eng'],1,{workerPath:'/ocr/worker.min.js',corePath:'/ocr/core',langPath:'/ocr',logger:m=>{if(m.status==='recognizing text')setOcr(t(`Распознаём текст: ${Math.round(m.progress*100)}%`));}});try{const result=await worker.recognize(file);setText(result.data.text);setOcr(result.data.text.trim()?t('Текст распознан. Проверьте его перед анализом.'):t('Текст не найден. Попробуйте более чёткое изображение.'));setTab('text');}finally{await worker.terminate();}}catch(e){setError(t('Не удалось распознать изображение. Проверьте локальные OCR-ресурсы или вставьте текст вручную.'));setOcr('');}finally{setOcrBusy(false);}}
 async function importFile(e){const file=e.target.files?.[0];e.target.value='';if(readOnly||!file)return;if(file.size>2*1024*1024){setError(t('Максимальный размер файла — 2 МБ.'));return;}setImportBusy(true);setError('');try{const content=await file.text();let items;if(file.name.toLowerCase().endsWith('.json')){const parsed=JSON.parse(content);items=Array.isArray(parsed)?parsed:parsed.items||parsed.cases;if(!items&&Array.isArray(parsed.messages)){items=parsed.messages.filter(m=>m.type==='message').map(m=>({text:Array.isArray(m.text)?m.text.map(t=>typeof t==='string'?t:t.text||'').join(''):m.text||'',platform:'telegram',author:m.from||''})).filter(m=>m.text.trim());}if(!Array.isArray(items))throw new Error(t('JSON должен содержать массив публикаций, поле items, cases или экспорт messages из Telegram.'));}else{items=content.split(/\r?\n\s*\r?\n/).filter(s=>s.trim()).map(s=>({text:s.trim(),platform}));}if(!items.length)throw new Error(t('В файле нет публикаций.'));await api('/api/import',{method:'POST',body:JSON.stringify({items:items.map(item=>({...item,platform:normalizePlatform(item.platform||platform)}))})});onImported();}catch(e){setError(e instanceof SyntaxError?t('Некорректный JSON.'):e.message);}finally{setImportBusy(false);}}
 return <div className="analyze-grid"><section className="panel analyze-panel"><div className="input-tabs"><button className={tab==='text'?'active':''} onClick={()=>setTab('text')}><FileText size={17}/>{t("Текст и ссылка")}</button><button className={tab==='image'?'active':''} onClick={()=>setTab('image')}><Image size={17}/>{t("Скриншот")}</button><button disabled={readOnly} className={tab==='import'?'active':''} onClick={()=>setTab('import')}><Upload size={17}/>{t("Импорт")}</button></div><form onSubmit={analyze} className="analyze-form">{error&&<div className="alert error" role="alert"><AlertTriangle size={17}/>{t(error)}</div>}{tab==='image'&&<div className="upload-zone"><Image size={32}/><h3>{t("Проверьте текст со скриншота")}</h3><p>{t("PNG, JPG, WebP · до 12 МБ. Русский, казахский и английский. Распознавание в браузере.")}</p><button type="button" className="button secondary" onClick={()=>imageRef.current.click()} disabled={ocrBusy}>{ocrBusy?<LoaderCircle className="spin" size={17}/>:<Upload size={17}/>}{t("Выбрать изображение")}</button><small>{t("Изображение остаётся в браузере. Проверьте распознанный текст перед отправкой.")}</small></div>}{tab==='import'?<div className="upload-zone"><Upload size={32}/><h3>{t("Несколько публикаций за один раз")}</h3><p>{t("JSON: публикации или экспорт Telegram Desktop.")}<br/>{t("TXT: публикации, разделённые пустой строкой.")}</p><button type="button" className="button primary" disabled={readOnly||importBusy} onClick={()=>fileRef.current.click()}>{importBusy?<LoaderCircle className="spin" size={16}/>:<Upload size={16}/>}{t("Импортировать файл")}</button><small>{t("До 2 МБ. Загруженные публикации сразу анализируются и сохраняются.")}</small><pre>{JSON.stringify([{text:t('Текст публикации'),platform:'telegram'}],null,2)}</pre></div>:<>{ocr&&<div className="alert info" role="status">{ocrBusy?<LoaderCircle className="spin" size={17}/>:<CircleCheck size={17}/>}<span>{t(ocr)}</span></div>}<span className="field-label" id="platform-label">{t("Платформа")}</span><div className="platform-options" role="group" aria-labelledby="platform-label">{PLATFORMS.map(p=><button key={p} type="button" aria-pressed={platform===p} className={platform===p?'chosen':''} onClick={()=>setPlatform(p)}><PlatformIcon platform={p}/>{t(PLATFORM_LABELS[p])}{platform===p&&<Check size={12}/>}</button>)}</div><div className="field-label-row"><label className="field-label" htmlFor="post-text">{t("Текст публикации или сообщения")}</label><span>{text.length.toLocaleString(getLanguage()==='kk'?'kk-KZ':'ru-RU')} / 30 000</span></div><textarea id="post-text" value={text} maxLength={30000} onChange={e=>setText(e.target.value)} placeholder={t("Вставьте текст, который кажется подозрительным. Например: «Вы выиграли приз! Для получения оплатите комиссию…»")} rows={9}/><label className="field-label" htmlFor="post-url">{t("Ссылка на источник")}<span>{t("необязательно")}</span></label><div className="url-input"><Link2 size={17}/><input id="post-url" type="url" placeholder="https://www.instagram.com/p/..." value={url} onChange={e=>setUrl(e.target.value)}/></div><p className="input-hint"><Info size={14}/>{t("Ссылка анализируется по структуре. Содержимое страницы автоматически не загружается.")}</p><div className="form-bottom"><span><ShieldCheck size={16}/>{!mode?L('Ожидаем режим сервера','Сервер режимі күтілуде'):readOnly?L('Результат не будет сохранён','Нәтиже сақталмайды'):(mode==='hosted_private'||mode==='hosted_admin')?L('Результат сохранится на сервере','Нәтиже серверде сақталады'):t('Проверка сохраняется локально')}</span><button className="button primary" disabled={!mode||busy||ocrBusy||(!text.trim()&&!url.trim())}>{busy?<LoaderCircle className="spin" size={17}/>:<ScanLine size={17}/>} {busy?t('Анализируем…'):t('Проверить контент')}</button></div></>}<input ref={imageRef} type="file" hidden accept="image/png,image/jpeg,image/webp" onChange={recognize}/><input ref={fileRef} disabled={readOnly} type="file" hidden accept=".json,.txt" onChange={importFile}/></form></section><aside className="analyze-aside">{!liveOnly&&<div className="panel example-panel"><span className="aside-icon"><Sparkles size={21}/></span><h3>{t("Начните с примера")}</h3><p>{t("Посмотрите, какие признаки замечает анализатор.")}</p>{EXAMPLES.map((x,i)=><button key={t(x.label)} className="example" onClick={()=>{setText(t(x.text));setPlatform(x.platform);setUrl('');setTab('text');setError('');}}><span className="example-number">0{i+1}</span><span>{t(x.label)}<small>{PLATFORM_LABELS[x.platform]}</small></span><ArrowUpRight size={17}/></button>)}</div>}<div className="privacy-note"><ShieldCheck size={19}/><div><h4>{t("Проверяйте без лишних данных")}</h4><p>{t("Не вставляйте пароли, коды доступа и персональные данные. Для анализа достаточно текста предложения.")}</p></div></div><div className="method-note"><h4>{t("Что вы получите")}</h4><p><Check size={15}/>{t("Оценку риска от 0 до 100")}</p><p><Check size={15}/>{t("Конкретные цитаты и признаки")}</p><p><Check size={15}/>{t("Ссылки и связанные аккаунты")}</p><p><Check size={15}/>{readOnly?L('Результат без сохранения','Сақталмайтын нәтиже'):t('Кейс для дальнейшей проверки')}</p></div></aside></div>;
}

function CaseAiDetail({analysis,evidence=[]}) {
 const ai=analysis?.ai;
 if(!ai||typeof ai!=='object')return null;
 const complete=ai.ok===true&&ai.status==='completed';
 const categories={gambling:L('Азартные игры','Құмар ойындар'),betting:L('Ставки / букмекер','Бәс тігу / букмекер'),phishing:L('Фишинг','Фишинг'),investment_scam:L('Инвестиционная схема','Инвестициялық схема'),none:L('Явных признаков не найдено','Айқын белгі табылмады'),uncertain:L('Недостаточно данных','Дерек жеткіліксіз')};
 const contexts={promotion:L('Реклама / продвижение','Жарнама / насихаттау'),news_or_warning:L('Новость / предупреждение','Жаңалық / ескерту'),uncertain:L('Контекст не определён','Мәнмәтін анықталмаған')};
 const failures={timeout:L('Превышено время анализа.','Талдау уақыты шегінен асты.'),busy:L('Модель была занята.','Модель бос болмады.'),model_missing:L('Модель не была установлена.','Модель орнатылмаған.'),vision_unavailable:L('Анализ изображений был недоступен.','Кескінді талдау қолжетімсіз болды.'),invalid_response:L('Ответ модели не прошёл проверку формата и цитат.','Модель жауабы пішім мен дәйексөз тексеруінен өтпеді.'),no_transcript:L('Речь не распознана.','Сөйлеу танылмады.')};
 const observations=complete&&Array.isArray(ai.observations)?ai.observations.filter(o=>o&&['visual','transcript'].includes(o.modality)&&typeof o.description==='string').slice(0,6):[];
 const sources=Array.isArray(evidence)?evidence.filter(e=>e&&['frame','audio','qr','vision'].includes(e.kind)):[];
 const clock=ms=>{if(!Number.isFinite(ms)||ms<0)return null;const seconds=Math.floor(ms/1000),minutes=Math.floor(seconds/60);return `${String(minutes).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;};
 const span=e=>{const start=clock(e?.startMs),end=clock(e?.endMs);return start?(end&&e.endMs>e.startMs?`${start}–${end}`:start):null;};
 const evidenceKind={frame:L('OCR кадра','Кадр OCR'),audio:L('Речь','Сөйлеу'),qr:'QR',vision:L('Вывод по кадру','Кадр туралы тұжырым')};
 const timestamps=[...new Set(sources.map(e=>{const value=span(e);return value?`${evidenceKind[e.kind]} · ${value}`:null;}).filter(Boolean))].slice(0,8);
 return <div className="detail-section ai-case-detail">
  <h3><Sparkles size={16} aria-hidden="true"/>{L('Наблюдения AI-модели','AI моделінің байқаулары')}<span className={`ai-case-state ${complete?'complete':''}`}>{complete?L('Анализ выполнен','Талдау орындалды'):L('AI не завершил анализ','AI талдауды аяқтамады')}</span></h3>
  <div className="ai-case-meta"><span>{L('Модель: ','Модель: ')}<strong>{ai.model||L('не указана','көрсетілмеген')}</strong></span>{Number.isFinite(ai.elapsedMs)&&ai.elapsedMs>=0&&<span>{L('Время анализа: ','Талдау уақыты: ')}{(ai.elapsedMs/1000).toLocaleString(getLanguage()==='kk'?'kk-KZ':'ru-RU',{maximumFractionDigits:1})} {L('с','с')}</span>}</div>
  {complete?<><div className="ai-case-classification"><div><span>{L('Категория модели','Модель санаты')}</span><strong>{categories[ai.category]||categories.uncertain}</strong></div><div><span>{L('Контекст модели','Модель мәнмәтіні')}</span><strong>{contexts[ai.context]||contexts.uncertain}</strong></div></div>{typeof ai.summary==='string'&&ai.summary&&<p className="ai-case-summary">{ai.summary}</p>}{observations.map((observation,i)=>{const source=sources.find(e=>observation.modality==='visual'?e.kind==='vision'&&e.text===observation.description:e.kind==='audio'&&typeof observation.quote==='string'&&observation.quote&&e.text?.includes(observation.quote));const timestamp=span(source);return <div className={`ai-observation ai-observation-${observation.modality}`} key={i}><div className="ai-observation-heading"><strong>{observation.modality==='visual'?L('Визуальное предположение','Кескін бойынша болжам'):L('Вывод по распознанной речи','Танылған сөйлеу бойынша тұжырым')}</strong>{timestamp&&<span><Clock3 size={12} aria-hidden="true"/>{timestamp}</span>}</div><p>{observation.description}</p>{observation.modality==='transcript'&&typeof observation.quote==='string'&&observation.quote&&<div className="ai-transcript-quote"><small>{L('Точная цитата из расшифровки','Танылған мәтіннен дәл дәйексөз')}</small><blockquote>«{observation.quote}»</blockquote></div>}{observation.modality==='visual'&&<small className="ai-observation-note">{L('Описание модели, не надпись и не дословная цитата из видео.','Бұл — модель сипаттамасы, видеодағы жазу не сөзбе-сөз дәйексөз емес.')}</small>}</div>;})}{!observations.length&&<p className="muted">{L('Модель не сохранила отдельных наблюдений. Это не гарантирует безопасность.','Модель жеке байқаулар сақтамады. Бұл қауіпсіздікке кепіл емес.')}</p>}</>:<p className="ai-case-unavailable">{failures[ai.reason]||L('В этой проверке не получено подтверждённого ответа AI.','Бұл тексеруде AI-дың расталған жауабы алынбады.')} {L('Оставшиеся сигналы относятся к правилам и распознанному тексту.','Қалған белгілер ережелер мен танылған мәтінге қатысты.')}</p>}
  {!!timestamps.length&&<div className="ai-evidence-times"><span>{L('Время фрагментов в видео','Видеодағы үзінді уақыты')}</span><div>{timestamps.map(value=><span key={value}>{value}</span>)}</div></div>}
  <p className="ai-case-note">{L('Вывод сохранён на языке анализа. Проверьте его по оригиналу: кадры выбраны частично, распознавание речи и модель могут ошибаться.','Қорытынды талдау кезіндегі тілде сақталған. Оны түпнұсқамен тексеріңіз: кадрлар іріктелген, сөйлеуді тану мен модель қателесуі мүмкін.')}</p>
 </div>;
}

function CaseDetail({item,onClose,onStatus,onDelete,readOnly}){const ref=useRef(),[copied,setCopied]=useState(false),[confirmDelete,setConfirmDelete]=useState(false),[pending,setPending]=useState(false);const a=localizedAnalysis(item.analysis||{});const generatedContent=item.provenance?.contentKind==='model_inference'||(a.ai?.ok===true&&String(item.text||'').startsWith('[AI inference / AI тұжырымы]'));const recognizedMedia=['frame','audio','qr'].includes(item.provenance?.kind);const displayText=generatedContent?String(item.text||'').replace(/^\[AI inference \/ AI тұжырымы\]\s*/, ''):item.text;useEffect(()=>{const previous=document.activeElement;ref.current?.focus();const original=document.body.style.overflow;document.body.style.overflow='hidden';function key(e){if(e.key==='Escape')onClose();if(e.key==='Tab'){const all=ref.current?.querySelectorAll('button:not(:disabled),select:not(:disabled),a[href],input:not(:disabled),textarea:not(:disabled),[tabindex="0"]');if(!all?.length)return;const first=all[0],last=all[all.length-1];const active=document.activeElement;const startsAtContainer=active===ref.current||!ref.current?.contains(active);if(e.shiftKey&&(active===first||startsAtContainer)){e.preventDefault();last.focus();}else if(!e.shiftKey&&(active===last||startsAtContainer)){e.preventDefault();first.focus();}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow=original;document.removeEventListener('keydown',key);previous?.focus();};},[]);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="case-drawer" role="dialog" aria-modal="true" aria-labelledby="case-detail-title" ref={ref} tabIndex={-1}><SearchExcerptNote item={item}/><div className="drawer-heading"><span><FolderSearch size={18}/>{t('Детали проверки')} {item.demo&&<span className="demo-badge">DEMO</span>}</span><button className="icon-button" aria-label={t("Закрыть детали")} onClick={onClose}><X size={21}/></button></div><div className="drawer-body">{item.stored===false?<div className="unsaved-result" role="status"><Info size={18}/><div><strong>{L('Результат не сохранён','Нәтиже сақталмады')}</strong><p>{L('Он не добавлен в сохранённые случаи или очередь проверки. После закрытия результата его нужно будет проанализировать снова.','Ол сақталған жағдайларға немесе тексеру кезегіне қосылмады. Нәтиже жабылғаннан кейін қайта талдау қажет болады.')}</p></div></div>:<a className="button secondary evidence-download" href={`/api/cases/${encodeURIComponent(item.id)}/evidence`} download><Download size={16}/>{L('Скачать пакет доказательств','Дәлелдер пакетін жүктеу')}<span>JSON · SHA-256</span></a>}<div className="case-detail-meta"><span className="platform"><PlatformIcon platform={item.platform}/>{t(PLATFORM_LABELS[item.platform]||item.platform)}</span><span>{new Date(item.createdAt).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}</span></div>{item.source==='public_telegram'&&<div className="alert info"><Info size={18}/><span>{L('Получено автоматически из открытой страницы Telegram.','Telegram ашық бетінен автоматты алынды.')} {(item.riskContext==='warning_or_news'||item.analysis?.riskContext==='warning_or_news')?L('Это сообщение или предупреждение о схеме; источник не объявляется мошенником.','Бұл схема туралы хабар не ескерту; дереккөз алаяқ деп саналмайды.'):L('Признаки в публикации требуют проверки контекста.','Жазбадағы белгілер контексті тексеруді қажет етеді.')}</span></div>}<h2 id="case-detail-title">{t(CATEGORIES[a.category]||'Результат анализа')}</h2><div className={`score-box ${a.level}`}><div><strong>{score(item)}<small>/100</small></strong><Risk level={a.level}/></div><div className="score-track"><span style={{width:`${score(item)}%`}}/></div><p>{a.summary||t('Оценка по обнаруженным текстовым признакам.')}</p></div><div className="detail-section"><h3>{t("Обнаруженные сигналы")}<span className="count-badge">{a.signals?.length||0}</span></h3>{a.signals?.length?a.signals.map((s,i)=><div className="signal" key={s.id||i}><div className="signal-head"><span className="signal-icon"><AlertTriangle size={14}/></span><strong>{s.label}</strong><small>+{s.weight}</small></div><p>{s.description}</p>{s.quote&&<blockquote>«{s.quote}»</blockquote>}</div>):<p className="muted">{t("Явные признаки не обнаружены. Это не гарантирует безопасность предложения.")}</p>}</div><CaseAiDetail analysis={a} evidence={item.evidence}/><div className="detail-section"><div className="section-title"><h3>{generatedContent?L("Описание, созданное моделью","Модель жасаған сипаттама"):recognizedMedia?L("Распознанный контент","Танылған мазмұн"):t("Исходный контент")}</h3><button className="text-button" onClick={async()=>{try{await navigator.clipboard.writeText(item.text||item.url||'');setCopied(true);}catch{setCopied(false);}}}>{copied?<Check size={14}/>:<Copy size={14}/>} {copied?t('Скопировано'):t('Копировать')}</button></div><div className="original-text">{displayText||t('Текст публикации не добавлен.')}</div>{generatedContent&&<p className="ai-case-note">{L('Этот текст составлен моделью по кадру. Он не является текстом публикации или расшифровкой речи.','Бұл мәтінді модель кадр бойынша құрастырған. Ол жазбаның мәтіні немесе сөйлеудің транскрипті емес.')}</p>}{item.url&&<p className="source-url"><Link2 size={14}/><span>{item.url}</span></p>}</div><div className="detail-section"><h3>{t("Найденные сущности")}</h3><div className="entity-list">{Object.entries(a.entities||{}).flatMap(([kind,values])=>(Array.isArray(values)?values:[]).map((v,i)=><span key={`${kind}-${i}`} title={kind}>{typeof v==='string'?v:JSON.stringify(v)}</span>))}{!Object.values(a.entities||{}).some(v=>Array.isArray(v)&&v.length)&&<p className="muted">{t("Ссылки, номера и аккаунты не найдены.")}</p>}</div></div><div className="detail-disclaimer"><Info size={17}/><p>{Array.isArray(a.limitations)?a.limitations.join(' '):a.limitations||t('Эвристическая оценка может ошибаться. Решение о мошенничестве требует проверки человеком.')}</p></div><>{item.stored!==false&&<><label className="field-label" htmlFor="case-status">{t("Решение модератора")}</label><select id="case-status" className="status-select" disabled={readOnly||pending} value={item.status||'new'} onChange={async e=>{setPending(true);await onStatus(item,e.target.value);setPending(false);}}>{Object.entries(STATUS).map(([id,label])=><option key={id} value={id}>{t(label)}</option>)}</select>{!readOnly&&(confirmDelete?<div className="delete-confirm"><span>{t("Удалить этот кейс без возможности отмены?")}</span><button className="button danger small" disabled={pending} onClick={async()=>{setPending(true);await onDelete(item);setPending(false);}}>{t("Удалить")}</button><button className="text-button" onClick={()=>setConfirmDelete(false)}>{t("Отмена")}</button></div>:<button className="delete-button" onClick={()=>setConfirmDelete(true)}><Trash2 size={15}/>{t("Удалить кейс")}</button>)}</>}</></div></section></div>;
}

function Metrics({metrics}){if(!metrics)return <div className="metrics-block"><p>{t("Загружаем метрики…")}</p></div>;if(metrics.available===false)return <div className="metrics-block"><h3>{t("Оценка качества")}</h3><p>{t("Метрики пока недоступны. Их можно рассчитать командой npm run evaluate.")}</p></div>;const percent=v=>Number.isFinite(Number(v))?`${(Number(v)*100).toFixed(1)}%`:'—';return <div className="metrics-block"><div className="section-title"><h3>{metrics.scope==='blind_test_holdout'?L('Оценка на отложенной части слепой выборки','Соқыр іріктеменің жасырын бөлігіндегі бағалау'):t("Оценка на тестовом наборе")}</h3><span className="demo-badge">{t("СИНТЕТИЧЕСКИЕ ДАННЫЕ")}</span></div><div className="metric-values">{[['Precision',metrics.precision],['Recall',metrics.recall],['F1',metrics.f1],['False positive rate',metrics.falsePositiveRate]].map(([label,value])=><div key={t(label)}><strong>{percent(value)}</strong><span>{t(label)}</span></div>)}</div><p>{metrics.total??'—'}{t(" искусственно составленных примеров. Эти показатели не отражают качество на реальных публикациях и не заменяют независимую оценку.")}</p>{metrics.confusionMatrix&&<div className="confusion-summary">TP: {metrics.confusionMatrix.tp} · FP: {metrics.confusionMatrix.fp} · TN: {metrics.confusionMatrix.tn} · FN: {metrics.confusionMatrix.fn}</div>}</div>;}
function Method(){const [metrics,setMetrics]=useState(null);useEffect(()=>{api('/api/metrics').then(setMetrics).catch(()=>setMetrics({available:false}));},[]);return <div className="method-grid"><section className="panel method-main"><div className="method-hero"><span className="aside-icon"><Fingerprint size={28}/></span><h2>{t("Сигналы, которые можно проверить")}</h2><p>{L('SafeNet сочетает текстовые правила с локальной предобученной моделью. Когда модель доступна и захват включён, она анализирует выбранные кадры Instagram и речь, распознанную Whisper. Состояние модели показано в мониторинге.','SafeNet мәтін ережелері мен жергілікті алдын ала үйретілген модельді біріктіреді. Модель қолжетімді және түсіру қосулы болса, Instagram-ның іріктелген кадрларын және Whisper таныған сөйлеуді талдайды. Модель күйі бақылау бетінде көрсетілген.')}</p></div><Metrics metrics={metrics}/><p className="ai-method-metrics-note">{L('Метрики выше относятся к синтетическому набору текстовых правил. Они не измеряют качество AI, распознавания видео или речи.','Жоғарыдағы метрикалар мәтін ережелерінің синтетикалық жиынтығына қатысты. Олар AI, видео не сөйлеуді тану сапасын өлшемейді.')}</p><div className="method-steps">{[{title:t('Находим конкретные признаки'),text:t('Фразы о гарантированном доходе, требование кода из SMS, комиссия за приз, приглашения в финансовые схемы и подозрительные ссылки.')},{title:t('Рассчитываем оценку риска'),text:L('Правила оценивают текст, а наблюдения модели получают отдельную эвристическую оценку. Итог использует большую из двух оценок. Средний риск — от 30, высокий — от 60 баллов. Балл не является вероятностью мошенничества.','Ережелер мәтінді бағалайды, ал модель байқаулары бөлек эвристикалық баға алады. Қорытынды екеуінің жоғары бағасын қолданады. Орташа қауіп — 30, жоғары қауіп — 60 балдан. Балл алаяқтық ықтималдығы емес.')},{title:t('Показываем доказательства'),text:L('Для текстовых сигналов сохраняются цитаты. Визуальные наблюдения модели помечены отдельно; для медиа сохраняется время фрагмента, когда оно известно. Исходный текст и модельное описание не смешиваются.','Мәтін белгілері үшін дәйексөздер сақталады. Модельдің кескін байқаулары бөлек белгіленеді; медиа үзіндісінің уақыты белгілі болса, сақталады. Бастапқы мәтін мен модель сипаттамасы араластырылмайды.')},{title:t('Оставляем решение человеку'),text:t('Модератор подтверждает или отклоняет подозрение после проверки источника и контекста. Подтверждение — ваше решение, а не автоматический вердикт.')}].map((s,i)=><div className="method-step" key={t(s.title)}><span>0{i+1}</span><div><h3>{t(s.title)}</h3><p>{s.text}</p></div></div>)}</div></section><aside><section className="panel method-limits"><AlertTriangle size={23}/><h3>{t("Границы анализа")}</h3><p>{L('Правила и AI могут пропустить обман или неверно понять новость, шутку и цитату. Анализ отдельных кадров не покрывает всё видео.','Ережелер мен AI алаяқтықты өткізіп алуы немесе жаңалықты, әзілді, дәйексөзді қате түсінуі мүмкін. Жеке кадрларды талдау бүкіл видеоны қамтымайды.')}</p><p>{t("Низкий балл не гарантирует безопасность. Личность автора, лицензии и реальные платежи не проверяются.")}</p><p>{L('Видео и звук анализируются локально после отдельного включения в расширении. Проверка перенаправлений запускается на странице «Проверка ссылок».','Видео мен дыбыс кеңейтімде бөлек қосылғаннан кейін жергілікті талданады. Бағыттаулар «Сілтемені тексеру» бетінде тексеріледі.')}</p><p>{t("Результаты не являются юридическим заключением.")}</p></section><section className="panel method-export"><Download size={22}/><h3>{t("Ваши данные — у вас")}</h3><p>{t("Выгрузите кейсы с оценками и сигналами для независимой проверки.")}</p><a href="/api/export?format=json" download className="button secondary">{t("Экспорт JSON")}<ArrowUpRight size={15}/></a></section></aside></div>;}
